+/** @emoji 🎭 `@spatial/js-machine-stately` provides XState views and actors for the rewritten static interaction definitions. */
+// #endregion Header
+
+import { createActor, setup } from "xstate";
+import type { InteractionDefinition } from "@spatial/js-core";
+import { loadInteractionDefinition } from "@spatial/js-core";
+
+export interface SpatialStateEdge {
+  readonly from: string;
+  readonly to: string;
+  readonly on: string;
+  readonly guard: string | null;
+}
+
+export interface SpatialStateMachineView {
+  readonly interactionId: string;
+  readonly initial: string;
+  readonly states: readonly { readonly id: string; readonly final: boolean }[];
+  readonly edges: readonly SpatialStateEdge[];
+}
+
+export function buildStateMachineView(interaction: string | InteractionDefinition): SpatialStateMachineView {
+  const spec = typeof interaction === "string" ? loadInteractionDefinition(interaction) : interaction;
+  if (!spec) throw new Error(`Unknown interaction ${String(interaction)}.`);
+  return {
+    interactionId: spec.id,
+    initial: spec.machine.initial,
+    states: spec.machine.states.map((state) => ({ id: state.name, final: Boolean(state.final) })),
+    edges: spec.machine.states.flatMap((state) =>
+      (state.on ?? []).flatMap((handler) =>
+        handler.transitions.map((transition) => ({
+          from: state.name,
+          to: transition.target ?? state.name,
+          on: handler.event,
+          guard: transition.guard ?? null,
+        })),
+      ),
+    ),
+  };
+}
+
+export function createStatelyActor(interaction: string | InteractionDefinition) {
+  const spec = typeof interaction === "string" ? loadInteractionDefinition(interaction) : interaction;
+  if (!spec) throw new Error(`Unknown interaction ${String(interaction)}.`);
+  const states = Object.fromEntries(
+    spec.machine.states.map((state) => [
+      state.name,
+      {
+        on: Object.fromEntries(
+          (state.on ?? []).map((handler) => [handler.event, handler.transitions[0]?.target ?? state.name]),
+        ),
+      },
+    ]),
+  );
+  const machine = setup({
+    types: { events: {} as { type: string } },
+  }).createMachine({
+    id: spec.id,
+    initial: spec.machine.initial,
+    states,
+  });
+  return createActor(machine);
+}
+
+if (import.meta.vitest) {
+  const { describe, expect, it } = import.meta.vitest;
+
+  describe("@spatial/js-machine-stately views", () => {
+    it("builds a flat view over a spatial interaction", () => {
+      const view = buildStateMachineView({
+        schema: "spatial.interaction/v1",
+        id: "demo",
+        version: "1.0.0",
+        machine: {
+          initial: "idle",
+          states: [
+            { name: "idle", on: [{ event: "start", transitions: [{ target: "done" }] }] },
+            { name: "done", final: true },
+          ],
+        },
+        commit: { operation: { kind: "action", action: "noop" } },
+      });
+      expect(view.initial).toBe("idle");
+      expect(view.edges).toEqual([{ from: "idle", to: "done", on: "start", guard: null }]);
+    });
+
+    it("creates an actor that mirrors the first transition per event", () => {
+      const actor = createStatelyActor({
+        schema: "spatial.interaction/v1",
+        id: "demo",
+        version: "1.0.0",
+        machine: {
+          initial: "idle",
+          states: [
