+            { name: "done", final: true },
+          ],
+        },
+        commit: { operation: { kind: "action", action: "noop" } },
+      });
+      actor.start();
+      actor.send({ type: "start" });
+      expect(String(actor.getSnapshot().value)).toBe("done");
+    });
+  });
