/** @emoji 🔍 "/spatial/js-query" provides data-first selectors over the rewritten spatial core models and model spaces. */
// #endregion Header

import { Model, ModelSpace, listModelObjectsByTypology, listObjectPrimitives, type PrimitiveKind, type SpatialObject, type SpatialPrimitive } from "@spatial/js-core";

export interface ObjectQuery {
  readonly typologyId?: string;
  readonly attributeDefinitionId?: string;
  readonly primitiveKinds?: readonly PrimitiveKind[];
}

export interface QueryRow {
  readonly object: SpatialObject;
  readonly primitives: readonly SpatialPrimitive[];
}

export function queryObjects(model: Model, space: ModelSpace, query: ObjectQuery = {}): readonly QueryRow[] {
  const source = query.typologyId ? listModelObjectsByTypology(model, query.typologyId) : model.listObjects();
  const allowedKinds = query.primitiveKinds ? new Set(query.primitiveKinds) : null;
  return source
    .filter((object) => query.attributeDefinitionId ? object.attributes.some((attribute) => attribute.definitionId === query.attributeDefinitionId) : true)
    .map((object) => ({ object, primitives: listObjectPrimitives(space, object) }))
    .filter((row) => allowedKinds ? row.primitives.some((primitive) => allowedKinds.has(primitive.kind)) : true);
}

export function groupObjectsByTypology(model: Model): Readonly<Record<string, readonly SpatialObject[]>> {
  const groups: Record<string, SpatialObject[]> = {};
  for (const object of model.listObjects()) {
    if (!groups[object.typologyId]) groups[object.typologyId] = [];
    groups[object.typologyId]!.push(object);
  }
  return groups;
}

export function collectPrimitiveKinds(rows: readonly QueryRow[]): readonly PrimitiveKind[] {
  return [...new Set(rows.flatMap((row) => row.primitives.map((primitive) => primitive.kind)))];
}

